def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

@app.delete('/items/{item_id}', status_code=204)
def delete_item(item_id: int, db: Session = Depends(get_db)):
    item = db.get(Item, item_id)
    if not item:
        raise HTTPException(404, 'not found')
    db.delete(item)
    db.commit()
